using Client.Files.IService;
using Client.Files.IService.Models.Request;
using System.ComponentModel;

namespace Client.File.Test
{
    public class FileServiceTest
    {
        private IFileService _fileService;

        public FileServiceTest(IFileService fileService)
        {
            _fileService = fileService;
        }

        [Fact]
        [Description("проверка на создание файла")]
        public async void Createfile()
        {
            var createFile = await _fileService.CreateFile(new CreateFileRequest
            {
                name = "photo.jpg",
                mimeType = "image/jpeg",
                File = Convert.FromBase64String(@"")
            });

            Assert.True(!string.IsNullOrWhiteSpace(createFile.Data.id));
        }

        [Fact]
        [Description("проверка на получение файла")]
        public async void GetFile()
        {
            var getFile = await _fileService.GetFile(new GetFileRequest
            {
                id = "1uispJPhuLB7pvrMgTNuBymtdFT7RmwtR"
            });

            Assert.True(!string.IsNullOrWhiteSpace(getFile.Data.id));
            Assert.True(!string.IsNullOrWhiteSpace(getFile.Data.webViewLink));
        }

        [Fact]
        [Description("проверка на обновление файла")]
        public async void UpdateFile()
        {
            var updateFile = await _fileService.UpdateFile(new UpdateFileRequest
            {
                Id = "1mRhj1nvJlpHTqII0leAVp9CUcAwV49rv",
                //File = 
            });

            Assert.True(!string.IsNullOrWhiteSpace(updateFile.Data.id));
        }

        [Fact]
        [Description("проверка на удаление файла")]
        public async void DeleteFile()
        {
            var deleteFile = await _fileService.DeleteFile(new DeleteFileRequest
            {
                id = "1sQW8eNHlxVYjqfeZReM9HERZBKitZPNV"
            });

            Assert.Null(deleteFile.ErrorMessage);
        }
    }
}